  2021	/**
  2022	 * xmlXIncludeLoadNode:
  2023	 * @ctxt: an XInclude context
  2024	 * @nr: the node number
  2025	 *
  2026	 * Find and load the infoset replacement for the given node.
  2027	 *
  2028	 * Returns 0 if substitution succeeded, -1 if some processing failed
  2029	 */
  2030	static int
  2031	xmlXIncludeLoadNode(xmlXIncludeCtxtPtr ctxt, int nr) {
  2032	    xmlNodePtr cur;
  2033	    xmlChar *href;
  2034	    xmlChar *parse;
  2035	    xmlChar *base;
  2036	    xmlChar *oldBase;
  2037	    xmlChar *URI;
  2038	    int xml = 1; /* default Issue 64 */
  2039	    int ret;
  2040	
  2041	    if (ctxt == NULL)
  2042		return(-1);
  2043	    if ((nr < 0) || (nr >= ctxt->incNr))
  2044		return(-1);
  2045	    cur = ctxt->incTab[nr]->ref;
  2046	    if (cur == NULL)
  2047		return(-1);
  2048	
  2049	    /*
  2050	     * read the attributes
  2051	     */
  2052	    href = xmlXIncludeGetProp(ctxt, cur, XINCLUDE_HREF);
  2053	    if (href == NULL) {
  2054		href = xmlStrdup(BAD_CAST ""); /* @@@@ href is now optional */
  2055		if (href == NULL)
  2056		    return(-1);
  2057	    }
  2058	    parse = xmlXIncludeGetProp(ctxt, cur, XINCLUDE_PARSE);
  2059	    if (parse != NULL) {
  2060		if (xmlStrEqual(parse, XINCLUDE_PARSE_XML))
