  2080	    if (base == NULL) {
  2081		URI = xmlBuildURI(href, ctxt->doc->URL);
  2082	    } else {
  2083		URI = xmlBuildURI(href, base);
  2084	    }
  2085	    if (URI == NULL) {
  2086		xmlChar *escbase;
  2087		xmlChar *eschref;
  2088		/*
  2089		 * Some escaping may be needed
  2090		 */
  2091		escbase = xmlURIEscape(base);
  2092		eschref = xmlURIEscape(href);
  2093		URI = xmlBuildURI(eschref, escbase);
  2094		if (escbase != NULL)
  2095		    xmlFree(escbase);
  2096		if (eschref != NULL)
  2097		    xmlFree(eschref);
  2098	    }
  2099	    if (URI == NULL) {
  2100		xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  2101		               XML_XINCLUDE_HREF_URI, "failed build URL\n", NULL);
  2102		if (parse != NULL)
  2103		    xmlFree(parse);
  2104		if (href != NULL)
  2105		    xmlFree(href);
  2106		if (base != NULL)
  2107		    xmlFree(base);
  2108		return(-1);
  2109	    }
  2110	#ifdef DEBUG_XINCLUDE
  2111	    xmlGenericError(xmlGenericErrorContext, "parse: %s\n",
  2112		    xml ? "xml": "text");
  2113	    xmlGenericError(xmlGenericErrorContext, "URI: %s\n", URI);
  2114	#endif
  2115	
  2116	    /*
  2117	     * Save the base for this include (saving the current one)
  2118	     */
  2119	    oldBase = ctxt->base;
  2120	    ctxt->base = base;
  2121	
  2122	    if (xml) {
  2123		ret = xmlXIncludeLoadDoc(ctxt, URI, nr);
  2124		/* xmlXIncludeGetFragment(ctxt, cur, URI); */
  2125	    } else {
  2126		ret = xmlXIncludeLoadTxt(ctxt, URI, nr);
  2127	    }
  2128	
  2129	    /*
  2130	     * Restore the original base before checking for fallback
  2131	     */
  2132	    ctxt->base = oldBase;
  2133	
  2134	    if (ret < 0) {
  2135		xmlNodePtr children;
  2136	
  2137		/*
  2138		 * Time to try a fallback if available
  2139		 */
  2140	#ifdef DEBUG_XINCLUDE
  2141		xmlGenericError(xmlGenericErrorContext, "error looking for fallback\n");
  2142	#endif
  2143		children = cur->children;
  2144		while (children != NULL) {
  2145		    if ((children->type == XML_ELEMENT_NODE) &&
  2146			(children->ns != NULL) &&
  2147			(xmlStrEqual(children->name, XINCLUDE_FALLBACK)) &&
  2148			((xmlStrEqual(children->ns->href, XINCLUDE_NS)) ||
  2149			 (xmlStrEqual(children->ns->href, XINCLUDE_OLD_NS)))) {
  2150			ret = xmlXIncludeLoadFallback(ctxt, children, nr);
  2151			break;
  2152		    }
  2153		    children = children->next;
  2154		}
  2155	    }
  2156	    if (ret < 0) {
  2157		xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  2158		               XML_XINCLUDE_NO_FALLBACK,
  2159			       "could not load %s, and no fallback was found\n",
  2160			       URI);
  2161	    }
  2162	
  2163	    /*
  2164	     * Cleanup
  2165	     */
  2166	    if (URI != NULL)
  2167		xmlFree(URI);
  2168	    if (parse != NULL)
  2169		xmlFree(parse);
  2170	    if (href != NULL)
  2171		xmlFree(href);
  2172	    if (base != NULL)
  2173		xmlFree(base);
  2174	    return(0);
  2175	}
