  2358	/**
  2359	 * xmlXIncludeDoProcess:
  2360	 * @ctxt: the XInclude processing context
  2361	 * @doc: an XML document
  2362	 * @tree: the top of the tree to process
  2363	 * @skipRoot: don't process the root node of the tree
  2364	 *
  2365	 * Implement the XInclude substitution on the XML document @doc
  2366	 *
  2367	 * Returns 0 if no substitution were done, -1 if some processing failed
  2368	 *    or the number of substitutions done.
  2369	 */
  2370	static int
  2371	xmlXIncludeDoProcess(xmlXIncludeCtxtPtr ctxt, xmlDocPtr doc, xmlNodePtr tree,
  2372	                     int skipRoot) {
  2373	    xmlNodePtr cur;
  2374	    int ret = 0;
  2375	    int i, start;
  2376	
  2377	    if ((doc == NULL) || (tree == NULL) || (tree->type == XML_NAMESPACE_DECL))
  2378		return(-1);
  2379	    if ((skipRoot) && (tree->children == NULL))
  2380	        return(-1);
  2381	    if (ctxt == NULL)
  2382		return(-1);
  2383	
  2384	    if (doc->URL != NULL) {
  2385		ret = xmlXIncludeURLPush(ctxt, doc->URL);
  2386		if (ret < 0)
  2387		    return(-1);
  2388	    }
  2389	    start = ctxt->incNr;
  2390	
  2391	    /*
  2392	     * TODO: The phases must run separately for recursive inclusions.
  2393	     *
  2394	     * - Phase 1 should start with top-level XInclude nodes, load documents,
  2395	     *   execute XPointer expressions, then process only the result nodes
  2396	     *   (not whole document, see bug #324081) and only for phase 1
  2397	     *   recursively. We will need a backreference from xmlNodes to
  2398	     *   xmlIncludeRefs to detect references that were already visited.
  2399	     *   This can also be used for proper cycle detection, see bug #344240.
  2400	     *
  2401	     * - Phase 2 should visit all top-level XInclude nodes and expand
  2402	     *   possible subreferences in the replacement recursively.
  2403	     *
  2404	     * - Phase 3 should finally replace the top-level XInclude nodes.
  2405	     *   It could also be run together with phase 2.
  2406	     */
  2407	
  2408	    /*
  2409	     * First phase: lookup the elements in the document
  2410	     */
  2411	    if (skipRoot)
  2412	        cur = tree->children;
  2413	    else
  2414	        cur = tree;
  2415	    do {
  2416		/* TODO: need to work on entities -> stack */
  2417	        if (xmlXIncludeTestNode(ctxt, cur) == 1) {
  2418	#ifdef FUZZING_BUILD_MODE_UNSAFE_FOR_PRODUCTION
  2419	            /*
  2420	             * Avoid superlinear expansion by limiting the total number
  2421	             * of replacements.
  2422	             */
  2423	            if (ctxt->incTotal >= 20)
  2424	                return(-1);
  2425	#endif
  2426	            ctxt->incTotal++;
  2427	            xmlXIncludePreProcessNode(ctxt, cur);
  2428	        } else if ((cur->children != NULL) &&
  2429	                   ((cur->type == XML_DOCUMENT_NODE) ||
  2430	                    (cur->type == XML_ELEMENT_NODE))) {
  2431	            cur = cur->children;
  2432	            continue;
  2433	        }
  2434	        do {
  2435	            if (cur == tree)
  2436	                break;
  2437	            if (cur->next != NULL) {
  2438	                cur = cur->next;
  2439	                break;
  2440	            }
  2441	            cur = cur->parent;
  2442	        } while (cur != NULL);
  2443	    } while ((cur != NULL) && (cur != tree));
  2444	
  2445	    /*
  2446	     * Second Phase : collect the infosets fragments
  2447	     */
  2448	    for (i = start;i < ctxt->incNr; i++) {
  2449	        xmlXIncludeLoadNode(ctxt, i);
  2450		ret++;
  2451	    }
  2452	
  2453	    /*
  2454	     * Third phase: extend the original document infoset.
  2455	     *
  2456	     * Originally we bypassed the inclusion if there were any errors
  2457	     * encountered on any of the XIncludes.  A bug was raised (bug
  2458	     * 132588) requesting that we output the XIncludes without error,
  2459	     * so the check for inc!=NULL || xptr!=NULL was put in.  This may
  2460	     * give some other problems in the future, but for now it seems to
  2461	     * work ok.
  2462	     *
  2463	     */
  2464	    for (i = ctxt->incBase;i < ctxt->incNr; i++) {
  2465		if ((ctxt->incTab[i]->inc != NULL) ||
  2466		    (ctxt->incTab[i]->emptyFb != 0))	/* (empty fallback) */
  2467		    xmlXIncludeIncludeNode(ctxt, i);
  2468	    }
  2469	
  2470	    if (doc->URL != NULL)
  2471		xmlXIncludeURLPop(ctxt);
  2472	    return(ret);
  2473	}
