  3697	    if (cur == NULL) return;
  3698	    if (cur->type == XML_NAMESPACE_DECL) {
  3699		xmlFreeNsList((xmlNsPtr) cur);
  3700		return;
  3701	    }
  3702	    if (cur->doc != NULL) dict = cur->doc->dict;
  3703	    while (1) {
  3704	        while ((cur->children != NULL) &&
  3705	               (cur->type != XML_DOCUMENT_NODE) &&
  3706	               (cur->type != XML_HTML_DOCUMENT_NODE) &&
  3707	               (cur->type != XML_DTD_NODE) &&
  3708	               (cur->type != XML_ENTITY_REF_NODE)) {
  3709	            cur = cur->children;
  3710	            depth += 1;
  3711	        }
  3712	
  3713	        next = cur->next;
  3714	        parent = cur->parent;
  3715		if ((cur->type == XML_DOCUMENT_NODE) ||
  3716	            (cur->type == XML_HTML_DOCUMENT_NODE)) {
  3717	            xmlFreeDoc((xmlDocPtr) cur);
  3718	        } else if (cur->type != XML_DTD_NODE) {
  3719	
  3720		    if ((__xmlRegisterCallbacks) && (xmlDeregisterNodeDefaultValue))
  3721			xmlDeregisterNodeDefaultValue(cur);
  3722	
  3723		    if (((cur->type == XML_ELEMENT_NODE) ||
  3724			 (cur->type == XML_XINCLUDE_START) ||
  3725			 (cur->type == XML_XINCLUDE_END)) &&
  3726			(cur->properties != NULL))
  3727			xmlFreePropList(cur->properties);
  3728		    if ((cur->type != XML_ELEMENT_NODE) &&
  3729			(cur->type != XML_XINCLUDE_START) &&
  3730			(cur->type != XML_XINCLUDE_END) &&
  3731			(cur->type != XML_ENTITY_REF_NODE) &&
  3732			(cur->content != (xmlChar *) &(cur->properties))) {
  3733			DICT_FREE(cur->content)
  3734		    }
  3735		    if (((cur->type == XML_ELEMENT_NODE) ||
  3736		         (cur->type == XML_XINCLUDE_START) ||
  3737			 (cur->type == XML_XINCLUDE_END)) &&
  3738			(cur->nsDef != NULL))
  3739			xmlFreeNsList(cur->nsDef);
  3740	
  3741		    /*
  3742		     * When a node is a text node or a comment, it uses a global static
  3743		     * variable for the name of the node.
  3744		     * Otherwise the node name might come from the document's
  3745		     * dictionary
  3746		     */
  3747		    if ((cur->name != NULL) &&
  3748			(cur->type != XML_TEXT_NODE) &&
  3749			(cur->type != XML_COMMENT_NODE))
  3750			DICT_FREE(cur->name)
  3751		    xmlFree(cur);
  3752		}
  3753	
  3754	        if (next != NULL) {
  3755		    cur = next;
  3756	        } else {
  3757	            if ((depth == 0) || (parent == NULL))
  3758	                break;
  3759	            depth -= 1;
  3760	            cur = parent;
  3761	            cur->children = NULL;
  3762	        }
  3763	    }
  3764	}
