  2504	
  2505	int
  2506	xmlXIncludeProcessTreeFlagsData(xmlNodePtr tree, int flags, void *data) {
  2507	    xmlXIncludeCtxtPtr ctxt;
  2508	    int ret = 0;
  2509	
  2510	    if ((tree == NULL) || (tree->type == XML_NAMESPACE_DECL) ||
  2511	        (tree->doc == NULL))
  2512	        return(-1);
  2513	
  2514	    ctxt = xmlXIncludeNewContext(tree->doc);
