  2177	/**
  2178	 * xmlXIncludeIncludeNode:
  2179	 * @ctxt: an XInclude context
  2180	 * @nr: the node number
  2181	 *
  2182	 * Implement the infoset replacement for the given node
  2183	 *
  2184	 * Returns 0 if substitution succeeded, -1 if some processing failed
  2185	 */
  2186	static int
  2187	xmlXIncludeIncludeNode(xmlXIncludeCtxtPtr ctxt, int nr) {
  2188	    xmlNodePtr cur, end, list, tmp;
  2189	
  2190	    if (ctxt == NULL)
  2191		return(-1);
  2192	    if ((nr < 0) || (nr >= ctxt->incNr))
  2193		return(-1);
  2194	    cur = ctxt->incTab[nr]->ref;
  2195	    if ((cur == NULL) || (cur->type == XML_NAMESPACE_DECL))
  2196		return(-1);
  2197	
  2198	    list = ctxt->incTab[nr]->inc;
  2199	    ctxt->incTab[nr]->inc = NULL;
  2200	    ctxt->incTab[nr]->emptyFb = 0;
  2201	
  2202	    /*
  2203	     * Check against the risk of generating a multi-rooted document
  2204	     */
  2205	    if ((cur->parent != NULL) &&
  2206		(cur->parent->type != XML_ELEMENT_NODE)) {
  2207		int nb_elem = 0;
  2208	
  2209		tmp = list;
  2210		while (tmp != NULL) {
  2211		    if (tmp->type == XML_ELEMENT_NODE)
  2212			nb_elem++;
  2213		    tmp = tmp->next;
  2214		}
  2215		if (nb_elem > 1) {
  2216		    xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  2217		                   XML_XINCLUDE_MULTIPLE_ROOT,
  2218			       "XInclude error: would result in multiple root nodes\n",
  2219				   NULL);
  2220	            xmlFreeNodeList(list);
  2221		    return(-1);
  2222		}
  2223	    }
  2224	
  2225	    if (ctxt->parseFlags & XML_PARSE_NOXINCNODE) {
  2226		/*
  2227		 * Add the list of nodes
  2228		 */
  2229		while (list != NULL) {
  2230		    end = list;
  2231		    list = list->next;
  2232	
  2233		    xmlAddPrevSibling(cur, end);
  2234		}
  2235	        /*
  2236	         * FIXME: xmlUnlinkNode doesn't coalesce text nodes.
  2237	         */
  2238		xmlUnlinkNode(cur);
  2239		xmlFreeNode(cur);
  2240	    } else {
  2241	        xmlNodePtr child, next;
  2242	
  2243		/*
  2244		 * Change the current node as an XInclude start one, and add an
  2245		 * XInclude end one
  2246		 */
  2247	        if (ctxt->incTab[nr]->fallback)
  2248	            xmlUnsetProp(cur, BAD_CAST "href");
  2249		cur->type = XML_XINCLUDE_START;
  2250	        /* Remove fallback children */
  2251	        for (child = cur->children; child != NULL; child = next) {
  2252	            next = child->next;
  2253	            xmlUnlinkNode(child);
  2254	            xmlFreeNode(child);
  2255	        }
  2256		end = xmlNewDocNode(cur->doc, cur->ns, cur->name, NULL);
  2257		if (end == NULL) {
  2258		    xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  2259		                   XML_XINCLUDE_BUILD_FAILED,
  2260				   "failed to build node\n", NULL);
  2261	            xmlFreeNodeList(list);
  2262		    return(-1);
  2263		}
  2264		end->type = XML_XINCLUDE_END;
  2265		xmlAddNextSibling(cur, end);
  2266	
  2267		/*
  2268		 * Add the list of nodes
  2269		 */
  2270		while (list != NULL) {
  2271		    cur = list;
  2272		    list = list->next;
  2273	
  2274		    xmlAddPrevSibling(end, cur);
  2275		}
  2276	    }
  2277	
  2278	
  2279	    return(0);
  2280	}
  2281	
  2282	/**
  2283	 * xmlXIncludeTestNode:
  2284	 * @ctxt: the XInclude processing context
  2285	 * @node: an XInclude node
  2286	 *
  2287	 * test if the node is an XInclude node
  2288	 *
  2289	 * Returns 1 true, 0 otherwise
  2290	 */
  2291	static int
  2292	xmlXIncludeTestNode(xmlXIncludeCtxtPtr ctxt, xmlNodePtr node) {
  2293	    if (node == NULL)
  2294		return(0);
  2295	    if (node->type != XML_ELEMENT_NODE)
  2296		return(0);
  2297	    if (node->ns == NULL)
  2298		return(0);
  2299	    if ((xmlStrEqual(node->ns->href, XINCLUDE_NS)) ||
  2300	        (xmlStrEqual(node->ns->href, XINCLUDE_OLD_NS))) {
  2301		if (xmlStrEqual(node->ns->href, XINCLUDE_OLD_NS)) {
  2302		    if (ctxt->legacy == 0) {
  2303	#if 0 /* wait for the XML Core Working Group to get something stable ! */
  2304			xmlXIncludeWarn(ctxt, node, XML_XINCLUDE_DEPRECATED_NS,
  2305		               "Deprecated XInclude namespace found, use %s",
  2306			                XINCLUDE_NS);
  2307	#endif
  2308		        ctxt->legacy = 1;
  2309		    }
  2310		}
  2311		if (xmlStrEqual(node->name, XINCLUDE_NODE)) {
  2312		    xmlNodePtr child = node->children;
  2313		    int nb_fallback = 0;
  2314	
  2315		    while (child != NULL) {
  2316			if ((child->type == XML_ELEMENT_NODE) &&
  2317			    (child->ns != NULL) &&
  2318			    ((xmlStrEqual(child->ns->href, XINCLUDE_NS)) ||
  2319			     (xmlStrEqual(child->ns->href, XINCLUDE_OLD_NS)))) {
  2320			    if (xmlStrEqual(child->name, XINCLUDE_NODE)) {
  2321				xmlXIncludeErr(ctxt, node,
  2322				               XML_XINCLUDE_INCLUDE_IN_INCLUDE,
  2323					       "%s has an 'include' child\n",
  2324					       XINCLUDE_NODE);
  2325				return(0);
  2326			    }
  2327			    if (xmlStrEqual(child->name, XINCLUDE_FALLBACK)) {
  2328				nb_fallback++;
  2329			    }
  2330			}
  2331			child = child->next;
  2332		    }
  2333		    if (nb_fallback > 1) {
  2334			xmlXIncludeErr(ctxt, node, XML_XINCLUDE_FALLBACKS_IN_INCLUDE,
  2335				       "%s has multiple fallback children\n",
  2336			               XINCLUDE_NODE);
  2337			return(0);
  2338		    }
  2339		    return(1);
  2340		}
  2341		if (xmlStrEqual(node->name, XINCLUDE_FALLBACK)) {
  2342		    if ((node->parent == NULL) ||
  2343			(node->parent->type != XML_ELEMENT_NODE) ||
  2344			(node->parent->ns == NULL) ||
  2345			((!xmlStrEqual(node->parent->ns->href, XINCLUDE_NS)) &&
  2346			 (!xmlStrEqual(node->parent->ns->href, XINCLUDE_OLD_NS))) ||
  2347			(!xmlStrEqual(node->parent->name, XINCLUDE_NODE))) {
  2348			xmlXIncludeErr(ctxt, node,
  2349			               XML_XINCLUDE_FALLBACK_NOT_IN_INCLUDE,
  2350				       "%s is not the child of an 'include'\n",
  2351				       XINCLUDE_FALLBACK);
  2352		    }
  2353		}
  2354	    }
  2355	    return(0);
  2356	}
