  2206		(cur->parent->type != XML_ELEMENT_NODE)) {
  2207		int nb_elem = 0;
  2208	
  2209		tmp = list;
  2210		while (tmp != NULL) {
  2211		    if (tmp->type == XML_ELEMENT_NODE)
  2212			nb_elem++;
  2213		    tmp = tmp->next;
  2214		}
