  2435	            if (cur == tree)
  2436	                break;
  2437	            if (cur->next != NULL) {
  2438	                cur = cur->next;
  2439	                break;
  2440	            }
  2441	            cur = cur->parent;
  2442	        } while (cur != NULL);
  2443	    } while ((cur != NULL) && (cur != tree));
