  4100	           * we are in trouble: we need a new reconciled namespace.
  4101	           * This is expensive
  4102	           */
  4103	          ret->ns = xmlNewReconciledNs(target->doc, target, cur->ns);
  4104	        }
  4105	      }
  4106	
  4107	    } else
