  4115		tmp = ret->children;
  4116		while (tmp != NULL) {
  4117		    /* tmp->parent = (xmlNodePtr)ret; */
  4118		    if (tmp->next == NULL)
  4119		        ret->last = tmp;
  4120		    tmp = tmp->next;
  4121		}
  4122	    }
  4123	    /*
  4124	     * Try to handle IDs
  4125	     */
  4126	    if ((target!= NULL) && (cur!= NULL) &&
  4127		(target->doc != NULL) && (cur->doc != NULL) &&
  4128		(cur->doc->ids != NULL) && (cur->parent != NULL)) {
