  4405	static xmlNodePtr
  4406	xmlStaticCopyNodeList(xmlNodePtr node, xmlDocPtr doc, xmlNodePtr parent) {
  4407	    xmlNodePtr ret = NULL;
  4408	    xmlNodePtr p = NULL,q;
  4409	
  4410	    while (node != NULL) {
  4411	#ifdef LIBXML_TREE_ENABLED
  4412		if (node->type == XML_DTD_NODE ) {
  4413		    if (doc == NULL) {
  4414			node = node->next;
  4415			continue;
  4416		    }
