  4418			q = (xmlNodePtr) xmlCopyDtd( (xmlDtdPtr) node );
  4419			if (q == NULL) return(NULL);
  4420			q->doc = doc;
  4421			q->parent = parent;
  4422			doc->intSubset = (xmlDtdPtr) q;
  4423			xmlAddChild(parent, q);
  4424		    } else {
  4425			q = (xmlNodePtr) doc->intSubset;
  4426			xmlAddChild(parent, q);
  4427		    }
  4428		} else
  4429	#endif /* LIBXML_TREE_ENABLED */
  4430		    q = xmlStaticCopyNode(node, doc, parent, 1);
  4431		if (q == NULL) return(NULL);
  4432		if (ret == NULL) {
  4433		    q->prev = NULL;
  4434		    ret = p = q;
  4435		} else if (p != q) {
  4436		/* the test is required if xmlStaticCopyNode coalesced 2 text nodes */
  4437		    p->next = q;
  4438		    q->prev = p;
  4439		    p = q;
  4440		}
  4441		node = node->next;
  4442	    }
  4443	    return(ret);
