  4044	static xmlAttrPtr
  4045	xmlCopyPropInternal(xmlDocPtr doc, xmlNodePtr target, xmlAttrPtr cur) {
  4046	    xmlAttrPtr ret;
  4047	
  4048	    if (cur == NULL) return(NULL);
  4049	    if ((target != NULL) && (target->type != XML_ELEMENT_NODE))
  4050	        return(NULL);
