  2021	/**
  2022	 * xmlXIncludeLoadNode:
  2023	 * @ctxt: an XInclude context
  2024	 * @nr: the node number
  2025	 *
  2026	 * Find and load the infoset replacement for the given node.
  2027	 *
  2028	 * Returns 0 if substitution succeeded, -1 if some processing failed
  2029	 */
  2030	static int
  2031	xmlXIncludeLoadNode(xmlXIncludeCtxtPtr ctxt, int nr) {
  2032	    xmlNodePtr cur;
  2033	    xmlChar *href;
  2034	    xmlChar *parse;
  2035	    xmlChar *base;
  2036	    xmlChar *oldBase;
  2037	    xmlChar *URI;
  2038	    int xml = 1; /* default Issue 64 */
  2039	    int ret;
  2040	
  2041	    if (ctxt == NULL)
  2042		return(-1);
  2043	    if ((nr < 0) || (nr >= ctxt->incNr))
  2044		return(-1);
  2045	    cur = ctxt->incTab[nr]->ref;
  2046	    if (cur == NULL)
  2047		return(-1);
  2048	
  2049	    /*
  2050	     * read the attributes
  2051	     */
  2052	    href = xmlXIncludeGetProp(ctxt, cur, XINCLUDE_HREF);
  2053	    if (href == NULL) {
  2054		href = xmlStrdup(BAD_CAST ""); /* @@@@ href is now optional */
  2055		if (href == NULL)
  2056		    return(-1);
  2057	    }
  2058	    parse = xmlXIncludeGetProp(ctxt, cur, XINCLUDE_PARSE);
  2059	    if (parse != NULL) {
  2060		if (xmlStrEqual(parse, XINCLUDE_PARSE_XML))
  2061		    xml = 1;
  2062		else if (xmlStrEqual(parse, XINCLUDE_PARSE_TEXT))
  2063		    xml = 0;
  2064		else {
  2065		    xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  2066		                   XML_XINCLUDE_PARSE_VALUE,
  2067				   "invalid value %s for 'parse'\n", parse);
  2068		    if (href != NULL)
  2069			xmlFree(href);
  2070		    if (parse != NULL)
  2071			xmlFree(parse);
  2072		    return(-1);
  2073		}
  2074	    }
  2075	
  2076	    /*
  2077	     * compute the URI
  2078	     */
  2079	    base = xmlNodeGetBase(ctxt->doc, cur);
  2080	    if (base == NULL) {
  2081		URI = xmlBuildURI(href, ctxt->doc->URL);
  2082	    } else {
  2083		URI = xmlBuildURI(href, base);
  2084	    }
  2085	    if (URI == NULL) {
  2086		xmlChar *escbase;
  2087		xmlChar *eschref;
  2088		/*
  2089		 * Some escaping may be needed
  2090		 */
  2091		escbase = xmlURIEscape(base);
  2092		eschref = xmlURIEscape(href);
  2093		URI = xmlBuildURI(eschref, escbase);
  2094		if (escbase != NULL)
  2095		    xmlFree(escbase);
  2096		if (eschref != NULL)
  2097		    xmlFree(eschref);
  2098	    }
  2099	    if (URI == NULL) {
  2100		xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  2101		               XML_XINCLUDE_HREF_URI, "failed build URL\n", NULL);
  2102		if (parse != NULL)
  2103		    xmlFree(parse);
  2104		if (href != NULL)
  2105		    xmlFree(href);
  2106		if (base != NULL)
  2107		    xmlFree(base);
  2108		return(-1);
  2109	    }
  2110	#ifdef DEBUG_XINCLUDE
  2111	    xmlGenericError(xmlGenericErrorContext, "parse: %s\n",
  2112		    xml ? "xml": "text");
  2113	    xmlGenericError(xmlGenericErrorContext, "URI: %s\n", URI);
  2114	#endif
  2115	
  2116	    /*
  2117	     * Save the base for this include (saving the current one)
  2118	     */
  2119	    oldBase = ctxt->base;
  2120	    ctxt->base = base;
  2121	
  2122	    if (xml) {
  2123		ret = xmlXIncludeLoadDoc(ctxt, URI, nr);
  2124		/* xmlXIncludeGetFragment(ctxt, cur, URI); */
  2125	    } else {
  2126		ret = xmlXIncludeLoadTxt(ctxt, URI, nr);
  2127	    }
  2128	
  2129	    /*
  2130	     * Restore the original base before checking for fallback
  2131	     */
  2132	    ctxt->base = oldBase;
  2133	
  2134	    if (ret < 0) {
  2135		xmlNodePtr children;
  2136	
  2137		/*
  2138		 * Time to try a fallback if available
  2139		 */
  2140	#ifdef DEBUG_XINCLUDE
  2141		xmlGenericError(xmlGenericErrorContext, "error looking for fallback\n");
  2142	#endif
  2143		children = cur->children;
  2144		while (children != NULL) {
  2145		    if ((children->type == XML_ELEMENT_NODE) &&
  2146			(children->ns != NULL) &&
  2147			(xmlStrEqual(children->name, XINCLUDE_FALLBACK)) &&
  2148			((xmlStrEqual(children->ns->href, XINCLUDE_NS)) ||
  2149			 (xmlStrEqual(children->ns->href, XINCLUDE_OLD_NS)))) {
  2150			ret = xmlXIncludeLoadFallback(ctxt, children, nr);
  2151			break;
  2152		    }
  2153		    children = children->next;
  2154		}
  2155	    }
  2156	    if (ret < 0) {
  2157		xmlXIncludeErr(ctxt, ctxt->incTab[nr]->ref,
  2158		               XML_XINCLUDE_NO_FALLBACK,
  2159			       "could not load %s, and no fallback was found\n",
  2160			       URI);
  2161	    }
  2162	
  2163	    /*
  2164	     * Cleanup
  2165	     */
  2166	    if (URI != NULL)
  2167		xmlFree(URI);
  2168	    if (parse != NULL)
  2169		xmlFree(parse);
  2170	    if (href != NULL)
  2171		xmlFree(href);
  2172	    if (base != NULL)
  2173		xmlFree(base);
  2174	    return(0);
  2175	}
