  3683	/**
  3684	 * xmlFreeNodeList:
  3685	 * @cur:  the first node in the list
  3686	 *
  3687	 * Free a node and all its siblings, this is a recursive behaviour, all
  3688	 * the children are freed too.
  3689	 */
  3690	void
  3691	xmlFreeNodeList(xmlNodePtr cur) {
  3692	    xmlNodePtr next;
  3693	    xmlNodePtr parent;
  3694	    xmlDictPtr dict = NULL;
