  1906		len = xmlBufLength(buf->buffer);
  1907		for (i = 0;i < len;) {
  1908		    int cur;
  1909		    int l;
  1910	
  1911		    cur = xmlStringCurrentChar(NULL, &content[i], &l);
  1912		    if (!IS_CHAR(cur)) {
