  1923			    xmlFreeParserInputBuffer(buf);
  1924			    xmlFree(URL);
  1925			    return(-1);
  1926			}
  1927		    } else {
  1928			xinclude_multibyte_fallback_used = 0;
  1929			xmlNodeAddContentLen(node, &content[i], l);
  1930		    }
  1931		    i += l;
  1932		}
  1933		xmlBufShrink(buf->buffer, len);
  1934	    }
  1935	    xmlFreeParserCtxt(pctxt);
