  1948	/**
  1949	 * xmlXIncludeLoadFallback:
  1950	 * @ctxt:  the XInclude context
  1951	 * @fallback:  the fallback node
  1952	 * @nr:  the xinclude node number
  1953	 *
  1954	 * Load the content of the fallback node, and store the result
  1955	 * in the XInclude context
  1956	 *
  1957	 * Returns 0 in case of success, -1 in case of failure
  1958	 */
  1959	static int
  1960	xmlXIncludeLoadFallback(xmlXIncludeCtxtPtr ctxt, xmlNodePtr fallback, int nr) {
  1961	    xmlXIncludeCtxtPtr newctxt;
  1962	    int ret = 0;
  1963	    int oldNbErrors = ctxt->nbErrors;
  1964	
  1965	    if ((fallback == NULL) || (fallback->type == XML_NAMESPACE_DECL) ||
  1966	        (ctxt == NULL))
  1967		return(-1);
  1968	    if (fallback->children != NULL) {
  1969		/*
  1970		 * It's possible that the fallback also has 'includes'
  1971		 * (Bug 129969), so we re-process the fallback just in case
  1972		 */
  1973		newctxt = xmlXIncludeNewContext(ctxt->doc);
  1974		if (newctxt == NULL)
  1975		    return (-1);
  1976		newctxt->_private = ctxt->_private;
  1977		newctxt->base = xmlStrdup(ctxt->base);	/* Inherit the base from the existing context */
  1978		xmlXIncludeSetFlags(newctxt, ctxt->parseFlags);
  1979	        newctxt->incTotal = ctxt->incTotal;
  1980	        if (xmlXIncludeDoProcess(newctxt, ctxt->doc, fallback, 1) < 0)
  1981	            ret = -1;
  1982	        ctxt->incTotal = newctxt->incTotal;
  1983		if (ctxt->nbErrors > oldNbErrors)
  1984		    ret = -1;
  1985		xmlXIncludeFreeContext(newctxt);
  1986	
  1987		ctxt->incTab[nr]->inc = xmlDocCopyNodeList(ctxt->doc,
  1988		                                           fallback->children);
  1989	        if (ctxt->incTab[nr]->inc == NULL)
  1990	            ctxt->incTab[nr]->emptyFb = 1;
  1991	    } else {
  1992	        ctxt->incTab[nr]->inc = NULL;
  1993		ctxt->incTab[nr]->emptyFb = 1;	/* flag empty callback */
  1994	    }
  1995	    ctxt->incTab[nr]->fallback = 1;
  1996	    return(ret);
  1997	}
