  4089	      } else {
  4090	        /*
  4091	         * we have to find something appropriate here since
  4092	         * we can't be sure, that the namespace we found is identified
  4093	         * by the prefix
  4094	         */
  4095	        if (xmlStrEqual(ns->href, cur->ns->href)) {
