  4253	    ret->type = node->type;
  4254	
  4255	    ret->doc = doc;
  4256	    ret->parent = parent;
  4257	    if (node->name == xmlStringText)
  4258		ret->name = xmlStringText;
  4259	    else if (node->name == xmlStringTextNoenc)
  4260		ret->name = xmlStringTextNoenc;
  4261	    else if (node->name == xmlStringComment)
  4262		ret->name = xmlStringComment;
  4263	    else if (node->name != NULL) {
  4264	        if ((doc != NULL) && (doc->dict != NULL))
