  4304	    if (!extended)
  4305		goto out;
  4306	    if (((node->type == XML_ELEMENT_NODE) ||
  4307	         (node->type == XML_XINCLUDE_START)) && (node->nsDef != NULL))
  4308	        ret->nsDef = xmlCopyNamespaceList(node->nsDef);
  4309	
  4310	    if (node->ns != NULL) {
  4311	        xmlNsPtr ns;
  4312	
  4313		ns = xmlSearchNs(doc, ret, node->ns->prefix);
  4314		if (ns == NULL) {
  4315		    /*
  4316		     * Humm, we are copying an element whose namespace is defined
  4317		     * out of the new tree scope. Search it in the original tree
  4318		     * and add it at the top of the new tree
  4319		     */
  4320		    ns = xmlSearchNs(node->doc, node, node->ns->prefix);
  4321		    if (ns != NULL) {
  4322		        xmlNodePtr root = ret;
  4323	
  4324			while (root->parent != NULL) root = root->parent;
  4325			ret->ns = xmlNewNs(root, ns->href, ns->prefix);
  4326			} else {
  4327				ret->ns = xmlNewReconciledNs(doc, ret, node->ns);
  4328		    }
  4329		} else {
  4330		    /*
  4331		     * reference the existing namespace definition in our own tree.
  4332		     */
  4333		    ret->ns = ns;
  4334		}
  4335	    }
  4336	    if (((node->type == XML_ELEMENT_NODE) ||
  4337	         (node->type == XML_XINCLUDE_START)) && (node->properties != NULL))
  4338	        ret->properties = xmlCopyPropList(ret, node->properties);
  4339	    if (node->type == XML_ENTITY_REF_NODE) {
  4340		if ((doc == NULL) || (node->doc != doc)) {
  4341		    /*
  4342		     * The copied node will go into a separate document, so
