  3830	    if (((cur->type == XML_ELEMENT_NODE) ||
  3831		 (cur->type == XML_XINCLUDE_START) ||
  3832		 (cur->type == XML_XINCLUDE_END)) &&
  3833		(cur->nsDef != NULL))
