  4188	/*
  4189	 * NOTE about the CopyNode operations !
  4190	 *
  4191	 * They are split into external and internal parts for one
  4192	 * tricky reason: namespaces. Doing a direct copy of a node
  4193	 * say RPM:Copyright without changing the namespace pointer to
  4194	 * something else can produce stale links. One way to do it is
  4195	 * to keep a reference counter but this doesn't work as soon
  4196	 * as one moves the element or the subtree out of the scope of
  4197	 * the existing namespace. The actual solution seems to be to add
  4198	 * a copy of the namespace at the top of the copied tree if
  4199	 * not available in the subtree.
  4200	 * Hence two functions, the public front-end call the inner ones
  4201	 * The argument "recursive" normally indicates a recursive copy
  4202	 * of the node with values 0 (no) and 1 (yes).  For XInclude,
  4203	 * however, we allow a value of 2 to indicate copy properties and
  4204	 * namespace info, but don't recurse on children.
  4205	 */
  4206	
  4207	static xmlNodePtr
  4208	xmlStaticCopyNode(xmlNodePtr node, xmlDocPtr doc, xmlNodePtr parent,
  4209	                  int extended) {
  4210	    xmlNodePtr ret;
  4211	
  4212	    if (node == NULL) return(NULL);
  4213	    switch (node->type) {
  4214	        case XML_TEXT_NODE:
  4215	        case XML_CDATA_SECTION_NODE:
  4216	        case XML_ELEMENT_NODE:
  4217	        case XML_DOCUMENT_FRAG_NODE:
  4218	        case XML_ENTITY_REF_NODE:
  4219	        case XML_ENTITY_NODE:
  4220	        case XML_PI_NODE:
  4221	        case XML_COMMENT_NODE:
  4222	        case XML_XINCLUDE_START:
  4223	        case XML_XINCLUDE_END:
  4224		    break;
  4225	        case XML_ATTRIBUTE_NODE:
  4226			return((xmlNodePtr) xmlCopyPropInternal(doc, parent, (xmlAttrPtr) node));
  4227	        case XML_NAMESPACE_DECL:
  4228		    return((xmlNodePtr) xmlCopyNamespaceList((xmlNsPtr) node));
  4229	
  4230	        case XML_DOCUMENT_NODE:
  4231	        case XML_HTML_DOCUMENT_NODE:
  4232	#ifdef LIBXML_TREE_ENABLED
  4233		    return((xmlNodePtr) xmlCopyDoc((xmlDocPtr) node, extended));
  4234	#endif /* LIBXML_TREE_ENABLED */
  4235	        case XML_DOCUMENT_TYPE_NODE:
  4236	        case XML_NOTATION_NODE:
  4237	        case XML_DTD_NODE:
  4238	        case XML_ELEMENT_DECL:
  4239	        case XML_ATTRIBUTE_DECL:
  4240	        case XML_ENTITY_DECL:
  4241	            return(NULL);
  4242	    }
  4243	
  4244	    /*
  4245	     * Allocate a new node and fill the fields.
  4246	     */
  4247	    ret = (xmlNodePtr) xmlMalloc(sizeof(xmlNode));
  4248	    if (ret == NULL) {
  4249		xmlTreeErrMemory("copying node");
  4250		return(NULL);
  4251	    }
  4252	    memset(ret, 0, sizeof(xmlNode));
  4253	    ret->type = node->type;
  4254	
  4255	    ret->doc = doc;
  4256	    ret->parent = parent;
  4257	    if (node->name == xmlStringText)
  4258		ret->name = xmlStringText;
  4259	    else if (node->name == xmlStringTextNoenc)
  4260		ret->name = xmlStringTextNoenc;
  4261	    else if (node->name == xmlStringComment)
  4262		ret->name = xmlStringComment;
  4263	    else if (node->name != NULL) {
  4264	        if ((doc != NULL) && (doc->dict != NULL))
  4265		    ret->name = xmlDictLookup(doc->dict, node->name, -1);
  4266		else
  4267		    ret->name = xmlStrdup(node->name);
  4268	    }
  4269	    if ((node->type != XML_ELEMENT_NODE) &&
  4270		(node->content != NULL) &&
  4271		(node->type != XML_ENTITY_REF_NODE) &&
  4272		(node->type != XML_XINCLUDE_END) &&
  4273		(node->type != XML_XINCLUDE_START)) {
  4274		ret->content = xmlStrdup(node->content);
  4275	    }else{
  4276	      if (node->type == XML_ELEMENT_NODE)
  4277	        ret->line = node->line;
  4278	    }
  4279	    if (parent != NULL) {
  4280		xmlNodePtr tmp;
  4281	
  4282		/*
  4283		 * this is a tricky part for the node register thing:
  4284		 * in case ret does get coalesced in xmlAddChild
  4285		 * the deregister-node callback is called; so we register ret now already
  4286		 */
  4287		if ((__xmlRegisterCallbacks) && (xmlRegisterNodeDefaultValue))
  4288		    xmlRegisterNodeDefaultValue((xmlNodePtr)ret);
  4289	
  4290	        /*
  4291	         * Note that since ret->parent is already set, xmlAddChild will
  4292	         * return early and not actually insert the node. It will only
  4293	         * coalesce text nodes and unnecessarily call xmlSetTreeDoc.
  4294	         * Assuming that the subtree to be copied always has its text
  4295	         * nodes coalesced, the somewhat confusing call to xmlAddChild
  4296	         * could be removed.
  4297	         */
  4298	        tmp = xmlAddChild(parent, ret);
  4299		/* node could have coalesced */
  4300		if (tmp != ret)
  4301		    return(tmp);
  4302	    }
  4303	
  4304	    if (!extended)
  4305		goto out;
  4306	    if (((node->type == XML_ELEMENT_NODE) ||
  4307	         (node->type == XML_XINCLUDE_START)) && (node->nsDef != NULL))
  4308	        ret->nsDef = xmlCopyNamespaceList(node->nsDef);
  4309	
  4310	    if (node->ns != NULL) {
  4311	        xmlNsPtr ns;
  4312	
  4313		ns = xmlSearchNs(doc, ret, node->ns->prefix);
  4314		if (ns == NULL) {
  4315		    /*
  4316		     * Humm, we are copying an element whose namespace is defined
  4317		     * out of the new tree scope. Search it in the original tree
  4318		     * and add it at the top of the new tree
  4319		     */
  4320		    ns = xmlSearchNs(node->doc, node, node->ns->prefix);
  4321		    if (ns != NULL) {
  4322		        xmlNodePtr root = ret;
  4323	
  4324			while (root->parent != NULL) root = root->parent;
  4325			ret->ns = xmlNewNs(root, ns->href, ns->prefix);
  4326			} else {
  4327				ret->ns = xmlNewReconciledNs(doc, ret, node->ns);
  4328		    }
  4329		} else {
  4330		    /*
  4331		     * reference the existing namespace definition in our own tree.
  4332		     */
  4333		    ret->ns = ns;
  4334		}
  4335	    }
  4336	    if (((node->type == XML_ELEMENT_NODE) ||
  4337	         (node->type == XML_XINCLUDE_START)) && (node->properties != NULL))
  4338	        ret->properties = xmlCopyPropList(ret, node->properties);
  4339	    if (node->type == XML_ENTITY_REF_NODE) {
  4340		if ((doc == NULL) || (node->doc != doc)) {
  4341		    /*
  4342		     * The copied node will go into a separate document, so
  4343		     * to avoid dangling references to the ENTITY_DECL node
  4344		     * we cannot keep the reference. Try to find it in the
  4345		     * target document.
  4346		     */
  4347		    ret->children = (xmlNodePtr) xmlGetDocEntity(doc, ret->name);
  4348		} else {
  4349	            ret->children = node->children;
  4350		}
  4351		ret->last = ret->children;
  4352	    } else if ((node->children != NULL) && (extended != 2)) {
  4353	        xmlNodePtr cur, insert;
  4354	
  4355	        cur = node->children;
  4356	        insert = ret;
  4357	        while (cur != NULL) {
  4358	            xmlNodePtr copy = xmlStaticCopyNode(cur, doc, insert, 2);
  4359	            if (copy == NULL) {
  4360	                xmlFreeNode(ret);
  4361	                return(NULL);
  4362	            }
  4363	
  4364	            /* Check for coalesced text nodes */
  4365	            if (insert->last != copy) {
  4366	                if (insert->last == NULL) {
  4367	                    insert->children = copy;
  4368	                } else {
  4369	                    copy->prev = insert->last;
  4370	                    insert->last->next = copy;
  4371	                }
  4372	                insert->last = copy;
  4373	            }
  4374	
  4375	            if (cur->children != NULL) {
  4376	                cur = cur->children;
  4377	                insert = copy;
  4378	                continue;
  4379	            }
  4380	
  4381	            while (1) {
  4382	                if (cur->next != NULL) {
  4383	                    cur = cur->next;
  4384	                    break;
  4385	                }
  4386	
  4387	                cur = cur->parent;
  4388	                insert = insert->parent;
  4389	                if (cur == node) {
  4390	                    cur = NULL;
  4391	                    break;
  4392	                }
  4393	            }
  4394	        }
  4395	    }
  4396	
  4397	out:
  4398	    /* if parent != NULL we already registered the node above */
  4399	    if ((parent == NULL) &&
  4400	        ((__xmlRegisterCallbacks) && (xmlRegisterNodeDefaultValue)))
  4401		xmlRegisterNodeDefaultValue((xmlNodePtr)ret);
  4402	    return(ret);
  4403	}
