  3703	    while (1) {
  3704	        while ((cur->children != NULL) &&
  3705	               (cur->type != XML_DOCUMENT_NODE) &&
  3706	               (cur->type != XML_HTML_DOCUMENT_NODE) &&
  3707	               (cur->type != XML_DTD_NODE) &&
  3708	               (cur->type != XML_ENTITY_REF_NODE)) {
  3709	            cur = cur->children;
  3710	            depth += 1;
  3711	        }
  3712	
  3713	        next = cur->next;
  3714	        parent = cur->parent;
  3715		if ((cur->type == XML_DOCUMENT_NODE) ||
  3716	            (cur->type == XML_HTML_DOCUMENT_NODE)) {
  3717	            xmlFreeDoc((xmlDocPtr) cur);
