  2041	    if (ctxt == NULL)
  2042		return(-1);
  2043	    if ((nr < 0) || (nr >= ctxt->incNr))
  2044		return(-1);
  2045	    cur = ctxt->incTab[nr]->ref;
  2046	    if (cur == NULL)
  2047		return(-1);
