  3863		    if (doc->intSubset == (xmlDtdPtr) cur)
  3864			doc->intSubset = NULL;
  3865		    if (doc->extSubset == (xmlDtdPtr) cur)
  3866			doc->extSubset = NULL;
  3867		}
  3868	    }
  3869	    if (cur->type == XML_ENTITY_DECL) {
  3870	        xmlDocPtr doc;
  3871		doc = cur->doc;
