  4307	         (node->type == XML_XINCLUDE_START)) && (node->nsDef != NULL))
  4308	        ret->nsDef = xmlCopyNamespaceList(node->nsDef);
  4309	
  4310	    if (node->ns != NULL) {
  4311	        xmlNsPtr ns;
  4312	
  4313		ns = xmlSearchNs(doc, ret, node->ns->prefix);
  4314		if (ns == NULL) {
  4315		    /*
  4316		     * Humm, we are copying an element whose namespace is defined
  4317		     * out of the new tree scope. Search it in the original tree
  4318		     * and add it at the top of the new tree
  4319		     */
  4320		    ns = xmlSearchNs(node->doc, node, node->ns->prefix);
  4321		    if (ns != NULL) {
  4322		        xmlNodePtr root = ret;
  4323	
  4324			while (root->parent != NULL) root = root->parent;
  4325			ret->ns = xmlNewNs(root, ns->href, ns->prefix);
  4326			} else {
  4327				ret->ns = xmlNewReconciledNs(doc, ret, node->ns);
  4328		    }
  4329		} else {
  4330		    /*
  4331		     * reference the existing namespace definition in our own tree.
  4332		     */
  4333		    ret->ns = ns;
  4334		}
  4335	    }
  4336	    if (((node->type == XML_ELEMENT_NODE) ||
  4337	         (node->type == XML_XINCLUDE_START)) && (node->properties != NULL))
  4338	        ret->properties = xmlCopyPropList(ret, node->properties);
  4339	    if (node->type == XML_ENTITY_REF_NODE) {
  4340		if ((doc == NULL) || (node->doc != doc)) {
  4341		    /*
  4342		     * The copied node will go into a separate document, so
  4343		     * to avoid dangling references to the ENTITY_DECL node
  4344		     * we cannot keep the reference. Try to find it in the
  4345		     * target document.
  4346		     */
  4347		    ret->children = (xmlNodePtr) xmlGetDocEntity(doc, ret->name);
  4348		} else {
  4349	            ret->children = node->children;
  4350		}
  4351		ret->last = ret->children;
  4352	    } else if ((node->children != NULL) && (extended != 2)) {
  4353	        xmlNodePtr cur, insert;
  4354	
  4355	        cur = node->children;
  4356	        insert = ret;
  4357	        while (cur != NULL) {
  4358	            xmlNodePtr copy = xmlStaticCopyNode(cur, doc, insert, 2);
  4359	            if (copy == NULL) {
  4360	                xmlFreeNode(ret);
  4361	                return(NULL);
  4362	            }
  4363	
  4364	            /* Check for coalesced text nodes */
  4365	            if (insert->last != copy) {
  4366	                if (insert->last == NULL) {
  4367	                    insert->children = copy;
  4368	                } else {
  4369	                    copy->prev = insert->last;
  4370	                    insert->last->next = copy;
  4371	                }
  4372	                insert->last = copy;
  4373	            }
  4374	
  4375	            if (cur->children != NULL) {
  4376	                cur = cur->children;
  4377	                insert = copy;
  4378	                continue;
  4379	            }
  4380	
  4381	            while (1) {
  4382	                if (cur->next != NULL) {
  4383	                    cur = cur->next;
  4384	                    break;
  4385	                }
  4386	
  4387	                cur = cur->parent;
  4388	                insert = insert->parent;
  4389	                if (cur == node) {
  4390	                    cur = NULL;
  4391	                    break;
  4392	                }
  4393	            }
  4394	        }
  4395	    }
  4396	
  4397	out:
