  2101		               XML_XINCLUDE_HREF_URI, "failed build URL\n", NULL);
  2102		if (parse != NULL)
  2103		    xmlFree(parse);
  2104		if (href != NULL)
  2105		    xmlFree(href);
  2106		if (base != NULL)
  2107		    xmlFree(base);
  2108		return(-1);
  2109	    }
