  2158		               XML_XINCLUDE_NO_FALLBACK,
  2159			       "could not load %s, and no fallback was found\n",
  2160			       URI);
  2161	    }
  2162	
  2163	    /*
  2164	     * Cleanup
  2165	     */
  2166	    if (URI != NULL)
  2167		xmlFree(URI);
  2168	    if (parse != NULL)
  2169		xmlFree(parse);
  2170	    if (href != NULL)
  2171		xmlFree(href);
  2172	    if (base != NULL)
  2173		xmlFree(base);
  2174	    return(0);
  2175	}
